import type { AppIcon } from "apps";

// Generated by scripts/icon.ts from Simple Icons (CC0) "github".
export const icons: readonly AppIcon[] = [
  {
    "src": "data:image/svg+xml;base64,",
    "mimeType": "image/svg+xml",
    "theme": "light"
  },
  {
    "src": "data:image/svg+xml;base64,",
    "mimeType": "image/svg+xml",
    "theme": "dark"
  }
];

import {
  accountRouter,
  decodeJson,
  defineApp,
  defineProvider,
  mapResults,
  number,
  oauth2,
  object,
  router,
  secrets,
  string,
  toolAnnotations,
  withApprovals,
} from "apps";
import { mcpRouter } from "apps/mcp";
import { always } from "apps/operations/approval";
import { liveOpenapiRouter } from "apps/openapi";
import { icons } from "./icon.js";
import { options } from "./openapi.js";
import { mcpResult, restResult } from "./results.js";

const User = object({ id: number(), login: string(), avatar_url: string(), html_url: string() });

// GitHub's official remote MCP server, default toolsets. It accepts the same tokens as the REST API.
const mcpUrl = "https://api.githubcopilot.com/mcp/";

const github = defineProvider({
  name: "GitHub",
  hosts: ["api.github.com", "api.githubcopilot.com"],
  auth: {
    // First, so the connect page starts with it. GitHub registers no clients, but Executor Cloud has
    // its own GitHub App for exactly these endpoints with no scopes (a GitHub App's permissions are
    // set on the app), so signing in there needs no OAuth app of the user's own. Elsewhere the
    // connect page asks for a client: register a GitHub App, since an OAuth app's token without
    // scopes can only read public data.
    oauth: oauth2({
      authorizationUrl: "https://github.com/login/oauth/authorize",
      tokenUrl: "https://github.com/login/oauth/access_token",
      tokenEndpointAuthMethod: "client_secret_post",
      scopes: [],
    }),
    token: secrets({
      label: "Personal access token",
      fields: object({ token: string({ minLength: 1 }) }),
    }),
  },
  async health({ account, fetch, signal }) {
    const token = account.method === "oauth" ? account.fields.access_token : account.fields.token;
    const response = await fetch("https://api.github.com/user", {
      signal,
      headers: { Authorization: `Bearer ${token}`, Accept: "application/vnd.github+json" },
    });
    const me = await decodeJson(response, User);
    return {
      accountInfo: {
        externalId: String(me.id),
        username: me.login,
        avatarUrl: me.avatar_url,
        profileUrl: me.html_url,
      },
    };
  },
});

type Account =
  | { method: "oauth"; fields: { access_token: string } }
  | { method: "token"; fields: { token: string } };

const token = (account: Account) => (account.method === "oauth" ? account.fields.access_token : account.fields.token);

export default defineApp(
  { user: { accounts: { github: github.many() } }, icons },
  async ({ user, cache, fetch, signal }) => {
    const accounts = user?.accounts.github ?? [];
    return {
      tools: router(
        {
          mcp: router(
            await accountRouter(
              accounts,
              async (account) =>
                withApprovals(
                  mapResults(
                    await mcpRouter({
                      url: mcpUrl,
                      account,
                      headers: { Authorization: `Bearer ${token(account)}` },
                      cache,
                      signal,
                    }),
                    mcpResult,
                  ),
                  (tool) => (toolAnnotations(tool)?.readOnlyHint === true ? undefined : always()),
                ),
              { signal },
            ),
            {
              title: "GitHub MCP",
              description:
                "GitHub's MCP server: repositories, code search, issues, pull requests and users, shaped for agents.",
            },
          ),
          api: router(
            await accountRouter(
              accounts,
              (account) =>
                withApprovals(
                  mapResults(
                    liveOpenapiRouter({ ...options, cache, fetch, signal, account }),
                    restResult,
                  ),
                  (tool) => (tool.kind === "mutation" ? always() : undefined),
                ),
              { signal },
            ),
            {
              title: "GitHub API",
              description:
                "Repositories, issues, pull requests, Actions, releases, organizations and the rest of the GitHub REST API.",
            },
          ),
        },
        {
          title: "GitHub",
          description:
            "Repositories, code search, issues, pull requests and users through GitHub's MCP server (mcp), plus Actions, releases, organizations and the rest of the GitHub REST API (api).",
          instructions: "Prefer the mcp tools; use the api tools for what they do not cover.",
          icons,
        },
      ),
    };
  },
);

import type { OpenapiToolNamesOptions } from "apps/openapi";

// GitHub's description declares no security schemes; every operation accepts a bearer token.
export const options = {
  source: {
    url: "https://raw.githubusercontent.com/github/rest-api-description/main/descriptions/api.github.com/api.github.com.json",
  },
  allowedOrigin: "https://api.github.com",
  securitySchemes: { bearer: { type: "http", scheme: "bearer" } },
  fallbackSecurity: [{ bearer: [] }],
  methods: {
    token: [{ scheme: "bearer", field: "token", part: "value", prefix: "" }],
    oauth: [{ scheme: "bearer", field: "access_token", part: "value", prefix: "" }],
  },
  oauth: [],
} satisfies OpenapiToolNamesOptions;

{
  "name": "@executor.sh/github",
  "description": "Repositories, code search, issues and pull requests through GitHub's MCP server, plus the rest of the GitHub REST API.",
  "private": true,
  "type": "module",
  "executor": {
    "title": "GitHub"
  },
  "dependencies": {
    "apps": "0.0.1-beta.104-basalt.15",
    "@modelcontextprotocol/sdk": "1.32.1"
  }
}

// Tool results land in agent transcripts, so they never carry a credential GitHub puts in a
// response unless the tool exists to mint it. REST and MCP results go through the same filter.

/** Short-lived credentials GitHub adds to ordinary reads, dropped from every result. */
const incidental = new Set(["temp_clone_token", "temp_download_token"]);

/**
 * The REST tools, named under `api`, that mint a credential because a person asked for one, and
 * the fields that carry it. Only these tools return those fields; every other result drops them.
 */
export const mintingTools: Readonly<Record<string, readonly string[]>> = {
  "actions.createRegistrationTokenForOrg": ["token"],
  "actions.createRegistrationTokenForRepo": ["token"],
  "actions.createRemoveTokenForOrg": ["token"],
  "actions.createRemoveTokenForRepo": ["token"],
  "actions.generateRunnerJitconfigForOrg": ["encoded_jit_config"],
  "actions.generateRunnerJitconfigForRepo": ["encoded_jit_config"],
  "apps.createFromManifest": ["client_secret", "pem", "webhook_secret"],
  "apps.createInstallationAccessToken": ["token"],
  "apps.resetToken": ["token"],
  "apps.scopeToken": ["token"],
};
const minted = new Set(Object.values(mintingTools).flat());
const none: ReadonlySet<string> = new Set();

// A link to a private file's raw content carries a `token` that reads the file without the
// account, such as a file's `download_url` or the link GitHub's MCP server gives for a large file.
const contentLink = /https:\/\/[\w-]+\.githubusercontent\.com\/[^\s"'<>\\]*/g;
const withoutLinkTokens = (text: string) =>
  text.includes("token=")
    ? text.replace(contentLink, (link) => {
        const url = new URL(link);
        if (!url.searchParams.has("token")) return link;
        url.searchParams.delete("token");
        return url.href;
      })
    : text;

/** `value` without credentials, other than the minted fields in `keep`; `value` itself if none. */
const clean = (value: unknown, keep: ReadonlySet<string>): unknown => {
  if (typeof value === "string") return withoutLinkTokens(value);
  if (typeof value !== "object" || value === null) return value;
  if (Array.isArray(value)) {
    const items = value.map((item) => clean(item, keep));
    return items.every((item, index) => item === value[index]) ? value : items;
  }
  // A secret-scanning alert's `secret` is the leaked credential itself.
  const alert = "secret_type" in value;
  let changed = false;
  const entries = Object.entries(value).flatMap(([key, item]) => {
    if (incidental.has(key) || (minted.has(key) && !keep.has(key)) || (alert && key === "secret")) {
      changed = true;
      return [];
    }
    const cleaned = clean(item, keep);
    if (cleaned !== item) changed = true;
    return [[key, cleaned] as const];
  });
  return changed ? Object.fromEntries(entries) : value;
};

/** A REST tool's result, keeping only the credential the tool mints, if it is listed. */
export const restResult = (result: unknown, tool: string) =>
  clean(result, Object.hasOwn(mintingTools, tool) ? new Set(mintingTools[tool]) : none);

const isMcpResult = (value: unknown): value is { readonly content: readonly unknown[] } =>
  typeof value === "object" && value !== null && "content" in value && Array.isArray(value.content);

const isText = (block: unknown): block is { readonly type: "text"; readonly text: string } =>
  typeof block === "object" &&
  block !== null &&
  "type" in block &&
  block.type === "text" &&
  "text" in block &&
  typeof block.text === "string";

const json = (text: string): unknown => {
  try {
    return JSON.parse(text);
  } catch {
    return undefined;
  }
};

/**
 * GitHub's MCP server writes GitHub's objects as JSON text, so a text block that is JSON is
 * filtered as that value. Any other text is a message, such as a large file's download link.
 */
const textBlock = (block: { readonly type: "text"; readonly text: string }) => {
  const parsed = json(block.text);
  if (parsed === undefined) return { ...block, text: withoutLinkTokens(block.text) };
  const cleaned = clean(parsed, none);
  return cleaned === parsed ? block : { ...block, text: JSON.stringify(cleaned) };
};

/** An MCP tool's result. No MCP tool mints a credential. */
export const mcpResult = (result: unknown) => {
  if (!isMcpResult(result)) return clean(result, none);
  const { content, ...rest } = result;
  return {
    ...Object.fromEntries(Object.entries(rest).map(([key, value]) => [key, clean(value, none)])),
    content: content.map((block) => (isText(block) ? textBlock(block) : clean(block, none))),
  };
};
